<?php require 'includes/functions.php';require_login();$q=db()->prepare('SELECT o.*,u.full_name,u.email,u.mobile FROM orders o JOIN users u ON u.id=o.user_id WHERE o.id=? AND o.user_id=?');$q->execute([(int)($_GET['id']??0),user()['id']]);$o=$q->fetch();if(!$o)go('orders.php');$q=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$q->execute([$o['id']]);$items=$q->fetchAll();$pageTitle='Invoice';require 'includes/header.php';require 'includes/navbar.php'; ?><main class="container my-5"><div class="d-flex justify-content-between align-items-start"><div><h1 class="tracking">OVERSO</h1><p>Oversized. Original. Yours.</p></div><button class="btn btn-dark" onclick="window.print()">Print Invoice</button></div><hr><div class="row"><div class="col-md-6"><h5>Bill to</h5><p><?=e($o['full_name'])?><br><?=e($o['email'])?><br><?=nl2br(e($o['billing_address']))?></p></div><div class="col-md-6 text-md-end"><h5>Invoice</h5><p>Order ID: <?=e($o['order_number'])?><br>Date: <?=date('d M Y',strtotime($o['created_at']))?><br>Payment: <?=e(strtoupper($o['payment_method']))?></p></div></div><table class="table"><thead><tr><th>Product</th><th>Size</th><th>Quantity</th><th class="text-end">Price</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?=e($i['product_name'])?></td><td><?=e($i['size'])?></td><td><?=$i['quantity']?></td><td class="text-end"><?=money($i['unit_price']*$i['quantity'])?></td></tr><?php endforeach ?></tbody></table><div class="ms-auto" style="max-width:320px"><p class="d-flex justify-content-between"><span>Subtotal</span><span><?=money($o['subtotal'])?></span></p><p class="d-flex justify-content-between"><span>Discount</span><span>-<?=money($o['coupon_discount'])?></span></p><p class="d-flex justify-content-between"><span>Tax</span><span><?=money($o['tax'])?></span></p><p class="d-flex justify-content-between"><span>Delivery</span><span><?=money($o['delivery_charge'])?></span></p><h5 class="d-flex justify-content-between"><span>Total</span><span><?=money($o['total_amount'])?></span></h5></div></main><?php require 'includes/footer.php'; ?>
